def parse_duration(s: str) -> int:
    total = 0
    num = ""
    for ch in (s + "x"):
        if ch.isdigit():
            num += ch
        elif ch in "hms":
            if not num:
                raise ValueError(f"invalid duration: {s}")
            total += int(num) * {"h": 3600, "m": 60, "s": 1}[ch]
            num = ""
        else:
            raise ValueError(f"invalid duration: {s}")
    if num:
        raise ValueError(f"invalid duration: {s}")
    return total
```

```python
import re

def parse_duration(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError(f"Expected a string, got {type(s).__name__}")
    if not s.strip():
        raise ValueError("Empty or whitespace-only duration string")

    pattern = re.compile(
        r"^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$",
        re.IGNORECASE,
    )
    match = pattern.match(s)
    if not match:
        raise ValueError(f"Invalid duration format: {s!r}")

    hours, minutes, seconds = match.groups()
    total = 0
    if hours:
        total += int(hours) * 3600
    if minutes:
        total += int(minutes) * 60
    if seconds:
        total += int(seconds)

    if total == 0:
        raise ValueError("Duration must be greater than zero")

    return total
