from typing import List, Tuple

def merge_intervals(intervals: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
    if not intervals:
        return []

    sorted_intervals = sorted(intervals, key=lambda x: x[0])
    merged = [sorted_intervals[0]]

    for start, end in sorted_intervals[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))

    return merged
```

```python
from typing import Iterable, Tuple

def merge_intervals(intervals: Iterable[Tuple[int, int]]) -> list[Tuple[int, int]]:
    sorted_intervals = sorted(intervals, key=lambda x: x[0])
    merged: list[Tuple[int, int]] = []
    for start, end in sorted_intervals:
        if not merged or merged[-1][1] < start:
            merged.append((start, end))
        else:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
    return merged
```

```python
import re

def parse_duration(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError(f"Expected string, got {type(s).__name__}")
    if not s.strip():
        raise ValueError("Empty or whitespace-only string")

    pattern = r"^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$"
    match = re.match(pattern, s)
    if not match:
        raise ValueError(f"Invalid duration format: {s!r}")

    hours, minutes, seconds = match.groups()
    return (int(hours or 0) * 3600) + (int(minutes or 0) * 60) + int(seconds or 0)
```

```python
import re

def parse_duration(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError(f"Expected a string, got {type(s).__name__}")
    if not s:
        raise ValueError("Empty duration string")

    pattern = r"^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$"
    match = re.match(pattern, s)
    if not match:
        raise ValueError(f"Invalid duration format: {s!r}")

    hours, minutes, seconds = match.groups()
    total = 0
    if hours:
        total += int(hours) * 3600
    if minutes:
        total += int(minutes) * 60
    if seconds:
        total += int(seconds)

    return total
