def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("Invalid duration string")

    total_seconds = 0
    pattern = ""

    # Split by known units to extract numbers
    # We will iterate through the string and parse segments
    current_num = ""
    for i, char in enumerate(s):
        if char.isdigit():
            current_num += char
        elif char in ('h', 'm', 's'):
            if not current_num:
                raise ValueError("Invalid duration string")
            num = int(current_num)
            current_num = ""

            if char == 'h':
                total_seconds += num * 3600
            elif char == 'm':
                total_seconds += num * 60
            elif char == 's':
                total_seconds += num
        else:
            raise ValueError("Invalid duration string")

    if current_num:
        raise ValueError("Invalid duration string")

    return total_seconds
